import{_ as e,o as t,c as r,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph Orchestrator Meeting 2023-02-21","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2023-02-21","date":"2023-02-21T00:00:00.000Z","updated":"2023-02-22T00:00:00.000Z","tags":["Ceph","Host Maintenance Mode","Emergency Flag","Maintenance Mode Enhancement","Ceph Community"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Orchestrator_Meeting_2023-02-21.md","filePath":"posts/2023/Ceph_Orchestrator_Meeting_2023-02-21.md","lastUpdated":1780459816000}'),i={name:"posts/2023/Ceph_Orchestrator_Meeting_2023-02-21.md"};function o(n,a,h,s,d,c){return t(),r("div",null,[...a[0]||(a[0]=[l('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph-主机维护模式增强功能讨论" tabindex="-1">会议主题：Ceph 主机维护模式增强功能讨论 <a class="header-anchor" href="#会议主题-ceph-主机维护模式增强功能讨论" aria-label="Permalink to &quot;会议主题：Ceph 主机维护模式增强功能讨论&quot;">​</a></h4><h4 id="与会人员-ceph-研发团队成员" tabindex="-1">与会人员：Ceph 研发团队成员 <a class="header-anchor" href="#与会人员-ceph-研发团队成员" aria-label="Permalink to &quot;与会人员：Ceph 研发团队成员&quot;">​</a></h4><h4 id="会议时间-2023-02-21" tabindex="-1">会议时间：2023-02-21 <a class="header-anchor" href="#会议时间-2023-02-21" aria-label="Permalink to &quot;会议时间：2023-02-21&quot;">​</a></h4><h4 id="会议地点-视频会议" tabindex="-1">会议地点：视频会议 <a class="header-anchor" href="#会议地点-视频会议" aria-label="Permalink to &quot;会议地点：视频会议&quot;">​</a></h4><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><strong>主机维护模式（Host Maintenance Mode）的强制执行问题</strong><ul><li>当前主机维护模式的强制标志（force flag）限制性较低，仅能强制停止其下的功能，但无法确保主机完全进入维护模式。</li><li>会议讨论了引入新标志的需求，以便在特定情况下（如PG降级）能够强制进入维护模式。</li></ul></li></ol><h4 id="讨论细节" tabindex="-1">讨论细节： <a class="header-anchor" href="#讨论细节" aria-label="Permalink to &quot;讨论细节：&quot;">​</a></h4><ul><li><strong>问题描述</strong>：现有强制标志在多种情况下无法确保主机完全进入维护模式，如PG降级等。</li><li><strong>解决方案</strong>：提出增加一个新的标志，允许在必要时强制进入维护模式，即便存在可能导致PG降级的条件。</li><li><strong>标志命名</strong>：讨论了多个名称，最终选定“我确实真的需要这个”（yes I really really mean it）作为标志名称，以体现操作的严重性和潜在风险。</li><li><strong>操作细节</strong>：该标志将允许用户在不考虑安全检查的情况下，强制停止所有守护进程，以便进行必要的维护工作。</li></ul><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>增加一个新的标志，用于在必要时强制进入主机维护模式，即使存在可能导致PG降级的条件。</li><li>标志名称为“我确实真的需要这个”（yes I really really mean it）。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>实现新的标志功能，并在代码中添加相应的警告和提示信息。</li><li>更新文档，明确新标志的使用场景和潜在风险。</li></ul><h4 id="其他讨论" tabindex="-1">其他讨论： <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论：&quot;">​</a></h4><ul><li>讨论了其他可能的标志名称和使用场景，但最终决定采用“我确实真的需要这个”（yes I really really mean it）。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><ul><li>会议在讨论完所有议题后结束，没有其他待讨论的新议题。</li></ul><h4 id="下次会议预告" tabindex="-1">下次会议预告： <a class="header-anchor" href="#下次会议预告" aria-label="Permalink to &quot;下次会议预告：&quot;">​</a></h4><ul><li>下次会议将根据项目进度和新的开发需求进行安排。</li></ul><p><strong>会议记录人：[记录人姓名]</strong></p><p><strong>审核人：[审核人姓名]</strong></p><p><strong>日期：2023-02-21</strong></p>',22)])])}const _=e(i,[["render",o]]);export{p as __pageData,_ as default};
